from collections import defaultdict
# where does a row start with 5? count rows of input with 5 at col0 vs output
i5=[r[0]==5 for r in inp]; o5=[r[0] for r in out if r[0]==2]; print(i5.count(True), len(o5))
for ri,(rii,rio) in enumerate(zip(inp,out)):
    if any(x!=y for x,y in zip(rii,rio)):
        nz=[j for j in range(len(rii)) if rii[j]!=rio[j]]
        if nz: print('row',ri,nz[:6], 'cols first diff',nz[0])

def f(g):
    h,w=len(g),len(g[0]); o=[[6]*w for _ in range(h)]
    for r in range(h):
        cols=[j for j in range(w) if g[r][j]==5]
        # find consecutive pairs of 5s: fill between with alternating 2,5 starting after first? check row1: cols11,13,15,17 -> out: col12=2,14=2,16=2; col13,15,17 stay 5. so fill even positions between min and max 5s with 2 (col j where j-min is odd).
        lo,hi=min(cols),max(cols)
        for j in range(lo+1,hi):
            o[r][j]=2 if (j-lo)%2 else 5
    return o
print(f(inp)==out)

