def f(g):
    h,w=len(g),len(g[0]); o=[row[:] for row in g]
    for r in range(h):
        cols=[j for j in range(w) if g[r][j]==5]
        if not cols: continue
        lo=min(cols); hi=max(cols)
        for j in range(lo+1,hi+1):
            o[r][j]=2 if (j-lo+1)%2 else 5
    return o
